package net.officefloor.hq.app.period;

import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Reopens a closed or soft-closed period: its due-total is live again. Refused for a role the permission matrix does not let reopen (by default
 *  anyone but a steward), and when
 *  the period is not closed. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, Out<Period> period) throws InvalidPeriodException, PeriodReopenException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.REOPEN, roles, settings)) {
            throw new PeriodReopenException("Your role may not reopen a period");
        }
        if (!found.fixed()) {
            throw new PeriodReopenException("The period is not closed");
        }
        period.set(periods.reopen(found));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a reopen that went through is recorded. */
public class RecordPeriodReopened {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Period period, Audit audit) {
        audit.record("PERIOD_REOPENED sheet=" + period.sheetId() + " by=" + (by == null ? "" : by)
                + " period=" + period.name());
    }
}
package net.officefloor.hq.app.period;

import java.util.Map;

/** A period on a sheet: its name and its from and to dates (yyyy-MM-dd), both inclusive, whether it
 *  is closed and, once closed, its due-total fixed at that moment (two decimals) and each person's
 *  due-total for it fixed then too, by person id (a person not in it shows 0.00). A soft-closed period
 *  ({@code soft}, not {@code closed}) has its figures fixed the same way, but claims due by a day in it can
 *  still be added and changed. Its cap (null: none) is the most OPEN or PENDING claims a person may
 *  have in it. Once fixed, each person's carried figure for it is fixed then too ({@code personCarried}).
 *  Each person's opening balance for it (pasted, added up), by person id ({@code personOpenings}); it is
 *  added to their live carried figure, and fixed into it when the period is closed or soft-closed. */
public record Period(String sheetId, String name, String from, String to, boolean closed,
        String closedTotal, Map<Long, String> personTotals, boolean soft, Integer cap,
        Map<Long, String> personCarried, Map<Long, String> personOpenings) {

    /** Whether its figures are fixed: closed or soft-closed. */
    public boolean fixed() {
        return closed || soft;
    }

    /** Whether the date (yyyy-MM-dd) falls inside it. */
    public boolean contains(String date) {
        return from.compareTo(date) <= 0 && date.compareTo(to) <= 0;
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriod {
    public void respond(@Val Period period, ObjectResponse<Period> response) {
        response.send(period);
    }
}
package net.officefloor.hq.app.period;

/** A period cannot be reopened: it is not closed, or the user's role may not reopen it. Refused and nothing
 *  is written. */
public class PeriodReopenException extends Exception {
    public PeriodReopenException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandlePeriodReopen {
    public void handle(@Parameter PeriodReopenException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
